425	    pub(super) async fn start_fresh_session_with_summary_hint(
426	        &mut self,
427	        tui: &mut tui::Tui,
428	        app_server: &mut AppServerSession,
429	        session_start_source: Option<ThreadStartSource>,
430	        initial_user_message: Option<crate::chatwidget::UserMessage>,
431	    ) {
432	        // Start a fresh in-memory session while preserving resumability via persisted rollout
433	        // history. If an initial message is provided, `enqueue_primary_thread_session` suppresses it
434	        // until the new session is configured and any replayed turns have been rendered.
435	        self.refresh_in_memory_config_from_disk_best_effort("starting a new thread")
436	            .await;
437	        let model = self.chat_widget.current_model().to_string();
438	        let config = self.fresh_session_config();
439	        let summary = session_summary(
440	            self.chat_widget.token_usage(),
441	            self.chat_widget.thread_id(),
442	            self.chat_widget.thread_name(),
443	            self.chat_widget.rollout_path().as_deref(),
444	        );
445	        self.shutdown_current_thread(app_server).await;
446	        let tracked_thread_ids: Vec<ThreadId> =
447	            self.thread_event_channels.keys().copied().collect();
448	        for thread_id in tracked_thread_ids {
449	            if let Err(err) = app_server.thread_unsubscribe(thread_id).await {
450	                tracing::warn!("failed to unsubscribe tracked thread {thread_id}: {err}");
451	            }
452	        }
453	        self.config = config.clone();
454	        match app_server
455	            .start_thread_with_session_start_source(&config, session_start_source)
456	            .await
457	        {
458	            Ok(started) => {
459	                if let Err(err) = self
460	                    .replace_chat_widget_with_app_server_thread(
461	                        tui,
462	                        app_server,
463	                        started,
464	                        initial_user_message,
465	                    )
466	                    .await
467	                {
468	                    self.chat_widget.add_error_message(format!(
469	                        "Failed to attach to fresh app-server thread: {err}"
470	                    ));
471	                } else if let Some(summary) = summary {
472	                    let mut lines: Vec<Line<'static>> = Vec::new();
473	                    if let Some(usage_line) = summary.usage_line {
474	                        lines.push(usage_line.into());
475	                    }
476	                    if let Some(command) = summary.resume_command {
477	                        let spans = vec!["To continue this session, run ".into(), command.cyan()];
478	                        lines.push(spans.into());
479	                    }
480	                    self.chat_widget.add_plain_history_lines(lines);
481	                }
482	            }
483	            Err(err) => {
484	                self.chat_widget.add_error_message(format!(
485	                    "Failed to start a fresh session through the app server: {err}"
486	                ));
487	                self.config.model = Some(model);
488	            }
489	        }
490	        tui.frame_requester().schedule_frame();
491	    }
