        let mut fork_config = self.config.clone();
        fork_config.ephemeral = true;

        // Side conversations should inherit the runtime settings the user has configured during the
        // current session (held on the chat widget), not the values persisted in the app config.
        fork_config.model = Some(self.chat_widget.current_model().to_string());
        fork_config.model_reasoning_effort = self.chat_widget.current_reasoning_effort();
        fork_config.service_tier = self.chat_widget.current_service_tier().map(str::to_string);

        let chat_config = self.chat_widget.config_ref();
        if let Err(err) = fork_config
            .permissions
            .approval_policy
            .set(chat_config.permissions.approval_policy.value())
        {
            tracing::warn!(%err, "failed to carry forward approval policy into side conversation");
        }
        if let Err(err) = fork_config
            .permissions
            .set_permission_profile(chat_config.permissions.permission_profile())
        {
            tracing::warn!(
                %err,
                "failed to carry forward permission profile into side conversation"
            );
        }
        fork_config.approvals_reviewer = chat_config.approvals_reviewer;

        fork_config.developer_instructions = Some(SIDE_DEVELOPER_INSTRUCTIONS.to_string());
        fork_config
